}

type Farmer = {
  id: string
  name: string
  village: string
  slug: string
  phone: string
  method: string
  pickup_locations?: string[] | null
  pickup_slots?: PickupSlots | null
}

type ProduceListing = {
  id: string
  name: string
  variety?: string
  emoji?: string
  image_url?: string
  method?: string
  status: string
  price_tier_1_price?: number
  price_tier_1_qty?: number
  price_tier_2_price?: number
