'use client'

import { useState, useRef, useEffect } from 'react'

type Suggestion = {
  name: string
  subtitle: string
  lat: number
  lng: number
}

// AP + Telangana bounding box for Nominatim
// viewbox=min_lng,max_lat,max_lng,min_lat
const VIEWBOX = '76.5,20.5,85.0,12.0'

async function searchLocations(q: string, signal: AbortSignal): Promise<Suggestion[]> {
  const url = new URL('https://nominatim.openstreetmap.org/search')
  url.searchParams.set('q', q)
  url.searchParams.set('countrycodes', 'in')
  url.searchParams.set('viewbox', VIEWBOX)
  url.searchParams.set('bounded', '1')
  url.searchParams.set('format', 'json')
  url.searchParams.set('limit', '6')
  url.searchParams.set('addressdetails', '1')
  url.searchParams.set('accept-language', 'en')

  const res = await fetch(url.toString(), { signal })
  if (!res.ok) throw new Error('Network error')
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const data: any[] = await res.json()

  const seen = new Set<string>()
  const results: Suggestion[] = []

  for (const item of data) {
    const addr = item.address ?? {}
    const name: string =
      addr.city || addr.town || addr.village || addr.hamlet ||
      addr.suburb || addr.county || item.name || ''
    if (!name || seen.has(name.toLowerCase())) continue
    seen.add(name.toLowerCase())

    const parts: string[] = []
    const district = addr.county || addr.state_district || addr.district
    if (district && district.toLowerCase() !== name.toLowerCase()) parts.push(district)
    if (addr.state) parts.push(addr.state)

    results.push({
      name,
      subtitle: parts.join(', '),
      lat: parseFloat(item.lat),
      lng: parseFloat(item.lon),
    })
  }

  return results
}

export default function LocationSearch({
  placeholder = 'Type your city or town... / పట్టణం వెతకండి',
  onSelect,
  initialValue = '',
}: {
  placeholder?: string
  onSelect: (lat: number, lng: number, name: string) => void
  initialValue?: string
}) {
  const [query, setQuery]           = useState(initialValue)
  const [suggestions, setSuggestions] = useState<Suggestion[]>([])
  const [loading, setLoading]       = useState(false)
  const [showDrop, setShowDrop]     = useState(false)
  const [noResults, setNoResults]   = useState(false)
  const abortRef   = useRef<AbortController | null>(null)
  const timerRef   = useRef<ReturnType<typeof setTimeout> | null>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  const doSearch = async (q: string) => {
    abortRef.current?.abort()
    if (q.trim().length < 3) {
      setSuggestions([])
      setNoResults(false)
      setLoading(false)
      return
    }
    abortRef.current = new AbortController()
    setLoading(true)
    setNoResults(false)
    try {
      const results = await searchLocations(q.trim(), abortRef.current.signal)
      setSuggestions(results)
      setNoResults(results.length === 0)
      setShowDrop(true)
    } catch (err: unknown) {
      if ((err as Error).name !== 'AbortError') {
        setSuggestions([])
        setNoResults(true)
      }
    } finally {
      setLoading(false)
    }
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value
    setQuery(val)
    if (timerRef.current) clearTimeout(timerRef.current)
    timerRef.current = setTimeout(() => doSearch(val), 400)
    if (val.trim().length < 3) {
      setSuggestions([])
      setNoResults(false)
      setShowDrop(false)
    }
  }

  const handleSelect = (s: Suggestion) => {
    setQuery(s.name)
    setSuggestions([])
    setShowDrop(false)
    setNoResults(false)
    onSelect(s.lat, s.lng, s.name)
  }

  // Close dropdown on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setShowDrop(false)
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  useEffect(() => () => { abortRef.current?.abort() }, [])

  return (
    <div ref={containerRef} className="relative">
      <div className="relative">
        <svg
          className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"
          width="18" height="18" viewBox="0 0 24 24" fill="none"
          stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"
        >
          <circle cx="11" cy="11" r="8" />
          <path d="m21 21-4.35-4.35" />
        </svg>
        <input
          type="text"
          value={query}
          onChange={handleChange}
          onFocus={() => { if (suggestions.length > 0) setShowDrop(true) }}
          placeholder={placeholder}
          autoComplete="off"
          className="w-full border-2 border-gray-200 rounded-xl pl-10 pr-10 py-3 text-base focus:border-green-500 focus:outline-none bg-white"
        />
        {loading && (
          <span className="absolute right-3 top-1/2 -translate-y-1/2">
            <span className="animate-spin inline-block w-4 h-4 border-2 border-green-600 border-t-transparent rounded-full" />
          </span>
        )}
        {!loading && query && (
          <button
            onClick={() => { setQuery(''); setSuggestions([]); setShowDrop(false); setNoResults(false) }}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 text-xl leading-none"
          >
            ×
          </button>
        )}
      </div>

      {showDrop && suggestions.length > 0 && (
        <div className="absolute z-30 top-full left-0 right-0 bg-white border border-gray-200 rounded-xl shadow-xl mt-1 overflow-hidden">
          {suggestions.map((s, i) => (
            <button
              key={i}
              onMouseDown={(e) => { e.preventDefault(); handleSelect(s) }}
              className="w-full text-left px-4 py-3 hover:bg-green-50 active:bg-green-100 border-b border-gray-100 last:border-0"
            >
              <p className="font-semibold text-sm text-gray-900">📍 {s.name}</p>
              {s.subtitle && (
                <p className="text-xs text-gray-500 mt-0.5">{s.subtitle}</p>
              )}
            </button>
          ))}
        </div>
      )}

      {showDrop && noResults && !loading && query.trim().length >= 3 && (
        <div className="absolute z-30 top-full left-0 right-0 bg-white border border-gray-200 rounded-xl shadow-xl mt-1 px-4 py-3">
          <p className="text-sm text-gray-500 text-center">
            No results found / ఫలితాలు లేవు
          </p>
          <p className="text-xs text-gray-400 text-center mt-0.5">
            Try a nearby larger town / దగ్గరలోని పెద్ద పట్టణం వెతకండి
          </p>
        </div>
      )}
    </div>
  )
}

