import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'

export const dynamic = 'force-dynamic'

export async function POST(req: NextRequest) {
  const body = await req.json().catch(() => ({}))
  const rawPhone: string = body.phone ?? ''
  const digits = rawPhone.replace(/\D/g, '').slice(-10)

  if (digits.length !== 10) {
    return NextResponse.json({ error: 'Enter a valid 10-digit phone number.' }, { status: 400 })
  }

  const fast2smsKey = process.env.FAST2SMS_API_KEY

  if (!fast2smsKey) {
    return NextResponse.json(
      { error: 'SMS service is not configured. Contact support.' },
      { status: 503 },
    )
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Invalidate any existing unused OTPs for this phone
  await supabase
    .from('farmer_otps')
    .update({ used: true })
    .eq('phone', digits)
    .eq('used', false)

  // Generate a 6-digit OTP, store with 10-minute expiry
  const otp = String(Math.floor(100000 + Math.random() * 900000))
  const expiresAt = new Date(Date.now() + 10 * 60 * 1000).toISOString()

  const { error: insertErr } = await supabase
    .from('farmer_otps')
    .insert({ phone: digits, otp, expires_at: expiresAt })

  if (insertErr) {
    return NextResponse.json({ error: insertErr.message }, { status: 500 })
  }

  // Send via Fast2SMS (works with any Indian number)
  const smsRes = await fetch('https://www.fast2sms.com/dev/bulkV2', {
    method: 'POST',
    headers: {
      authorization: fast2smsKey,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      route: 'q',
      message: `Your YourFamilyFarmer login code: ${otp}. Valid for 10 minutes. Do not share.`,
      numbers: digits,
      flash: 0,
    }),
  })

  if (!smsRes.ok) {
    const errBody = await smsRes.json().catch(() => ({}))
    return NextResponse.json(
      { error: errBody.message ?? 'Failed to send OTP. Please try again.' },
      { status: 502 },
    )
  }

  const smsJson = await smsRes.json().catch(() => ({}))
  if (smsJson.return === false) {
    return NextResponse.json(
      { error: smsJson.message?.[0] ?? 'Failed to send OTP. Please try again.' },
      { status: 502 },
    )
  }

  return NextResponse.json({ ok: true })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { scryptSync, randomBytes, timingSafeEqual } from 'crypto'

export const dynamic = 'force-dynamic'

function hashPassword(password: string): string {
  const salt = randomBytes(16).toString('hex')
  const hash = scryptSync(password, salt, 64).toString('hex')
  return `${salt}:${hash}`
}

function verifyPassword(password: string, stored: string): boolean {
  try {
    const [salt, hash] = stored.split(':')
    const hashBuffer = Buffer.from(hash, 'hex')
    const derived = scryptSync(password, salt, 64)
    return timingSafeEqual(hashBuffer, derived)
  } catch {
    return false
  }
}

export async function POST(req: NextRequest) {
  const body = await req.json().catch(() => ({}))
  const rawPhone: string = body.phone ?? ''
  const password: string = String(body.password ?? '').trim()
  const digits = rawPhone.replace(/\D/g, '').slice(-10)

  if (digits.length !== 10) {
    return NextResponse.json({ error: 'Enter a valid 10-digit phone number.' }, { status: 400 })
  }
  if (password.length < 4) {
    return NextResponse.json({ error: 'Password must be at least 4 characters.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Look up farmer by phone (any stored format)
  const { data: farmers } = await supabase
    .from('farmers')
    .select('id, name, slug, phone, password_hash')
    .or(
      [
        `phone.eq.${digits}`,
        `phone.eq.0${digits}`,
        `phone.eq.+91${digits}`,
        `phone.eq.91${digits}`,
      ].join(','),
    )
    .limit(1)

  const farmer = farmers?.[0]

  if (farmer) {
    if (!farmer.password_hash) {
      // Existing farmer logging in for first time after migration — set their password
      const hash = hashPassword(password)
      await supabase.from('farmers').update({ password_hash: hash, active: true }).eq('id', farmer.id)
      return NextResponse.json({ ok: true, farmerId: farmer.id, farmerSlug: farmer.slug })
    }

    if (!verifyPassword(password, farmer.password_hash)) {
      return NextResponse.json({ error: 'Incorrect password. Please try again.' }, { status: 401 })
    }

    await supabase.from('farmers').update({ active: true }).eq('id', farmer.id)
    return NextResponse.json({ ok: true, farmerId: farmer.id, farmerSlug: farmer.slug })
  }

  // New farmer — create account with this password
  const rand = Math.random().toString(36).slice(2, 6)
  const slug = `f-${digits}-${rand}`
  const hash = hashPassword(password)

  const { data: created, error: insertErr } = await supabase
    .from('farmers')
    .insert({
      phone: digits,
      slug,
      name: '',
      village: '',
      district: '',
      method: 'natural',
      region_slug: 'tadepalligudem',
      active: true,
      password_hash: hash,
    })
    .select('id, name, slug')
    .single()

  if (insertErr || !created) {
    return NextResponse.json({ error: 'Could not create account. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({ ok: true, farmerId: created.id, farmerSlug: created.slug })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'

export const dynamic = 'force-dynamic'

export async function POST(req: NextRequest) {
  const body = await req.json().catch(() => ({}))
  const rawPhone: string = body.phone ?? ''
  const otp: string = String(body.otp ?? '').trim()
  const digits = rawPhone.replace(/\D/g, '').slice(-10)

  if (digits.length !== 10 || !otp) {
    return NextResponse.json({ error: 'Phone and OTP are required.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Look up a valid (unused, not expired) OTP for this phone
  const { data: record } = await supabase
    .from('farmer_otps')
    .select('id')
    .eq('phone', digits)
    .eq('otp', otp)
    .eq('used', false)
    .gt('expires_at', new Date().toISOString())
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle()

  if (!record) {
    return NextResponse.json(
      { error: 'Invalid or expired OTP. Please try again.' },
      { status: 401 },
    )
  }

  // Mark OTP as used immediately so it can't be reused
  await supabase.from('farmer_otps').update({ used: true }).eq('id', record.id)

  // Look up farmer by any common phone format stored in DB
  const { data: farmers } = await supabase
    .from('farmers')
    .select('id, name, slug, phone')
    .or(
      [
        `phone.eq.${digits}`,
        `phone.eq.0${digits}`,
        `phone.eq.+91${digits}`,
        `phone.eq.91${digits}`,
      ].join(','),
    )
    .limit(1)

  let farmer = farmers?.[0]

  if (farmer) {
    // Make sure existing farmer is active
    await supabase.from('farmers').update({ active: true }).eq('id', farmer.id)
  } else {
    // Auto-create a minimal farmer record on first login
    const rand = Math.random().toString(36).slice(2, 6)
    const slug = `f-${digits}-${rand}`
    const { data: created, error: insertErr } = await supabase
      .from('farmers')
      .insert({
        phone: digits,
        slug,
        name: '',
        village: '',
        district: '',
        method: 'natural',
        region_slug: 'tadepalligudem',
        active: true,
      })
      .select('id, name, slug, phone')
      .single()

    if (insertErr || !created) {
      return NextResponse.json({ error: 'Could not create farmer profile.' }, { status: 500 })
    }
    farmer = created
  }

  return NextResponse.json({ ok: true, farmerId: farmer.id, farmerSlug: farmer.slug })
}

